class ResourceOwner {
    int* data; // Pointer managing owned resource
public:
    // Rvalue reference (&&) defines the Move Constructor
    ResourceOwner(ResourceOwner&& other) noexcept
        : data(other.data) {
        // Steal resource, ensure source is safe to destroy
        other.data = nullptr;
    }

    // Required part of the Rule of Five/Zero
    ResourceOwner& operator=(ResourceOwner&& other) noexcept;

    // Typically delete copy operations when moving
    ResourceOwner(const ResourceOwner&) = delete;
};

ResourceOwner r1;
// std::move converts lvalue r1 into an rvalue reference
// allowing the move constructor to be called.
ResourceOwner r2 = std::move(r1);
// r1 should not be used except for destruction/reassignment
